-- Purpose: absorb stablyai/orca (AI Orchestrator) knowledge into Simplicio neural memory.
-- 184 CLI commands + architecture + worktree/orchestration models + integration gaps.
-- Covers: overview, CLI surface, worktree id model, orchestration layer, integration points.
BEGIN;
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:orca:overview-v1','project_doc','seed://orca/overview','Orca — AI Orchestrator (stablyai/orca) overview','Orca (github.com/stablyai/orca, MIT) é um AI Orchestrator desktop cross-platform (macOS/Windows/Linux, Electron). Orquestra ANY CLI agent (Codex, Claude Code, OpenCode, Pi, Grok, Cursor, Copilot, Hermes Agent, Devin, Goose, Qwen Code, Kimi, etc.) em git worktrees isolados, cada um com terminais, tabs de browser embutido e estado de UI próprios. Inclui mobile companion (iOS/Android) para monitorar/steer agents, CLI pública `orca`, computer-use nativo (macOS), e bridge SSH para rodar agents em box remoto com port-forward. Principais diferenciais: parallel worktrees (fan-out N agents, comparar e merge do vencedor), design-mode (clica elemento UI -> manda HTML/CSS/screenshot pro agent), annotate AI diffs, GitHub/Linear nativos, rich repo previews. Stack: TypeScript/Electron + electron-vite, React renderer (shadcn/ui), pnpm workspaces, Playwright e2e, oxlint/oxfmt. Build: `pnpm build:desktop` + `build:native`; testes `pnpm test` (vitest).','README.md','21febc184851ae5f8874c39b85bbe431cb17d416e948d98ec8d71dc6d8227276','orca,ai-orchestrator,electron,worktrees,agents,overview',2.6);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:orca:cli-surface-v1','project_tool','seed://orca/cli-surface','Orca CLI — 184 comandos em 15 grupos (COMMAND_SPECS)','A CLI pública `orca` é definida por `src/cli/specs/index.ts` que flatMap 15 grupos de COMMAND_SPECS. Comandos completos (path arrays) extraídos de src/cli/specs/*.ts:
Grupos: core(open,status,serve,claude-teams,repo list/add/show/set-base-ref/search-refs,worktree list/show/current/create/set/ps/rm), project(setup-clone/create/delete/existing-folder/update/setups/list), file(diff/open/open-changed), automations(list/show/create/edit/remove/run/runs), browser-basic(snapshot,click,fill,type,select,check,uncheck,scroll,hover,focus,keypress,upload,wait,goto,back,reload,screenshot,full-screenshot,pdf,eval,exec,find,highlight,tab list/create/close/switch,console,capture start/stop,network,cookie get/set/delete,clipboard read/write,dialog accept/dismiss,storage local/session get/set/clear,set device/offline/headers/credentials/media,viewport,geolocation,intercept enable/disable/list,download,get,is,inserttext,dbclick,drag,mouse move/down/up/wheel,forward,scrollintoview,back), browser-advanced(=browser-basic estendido), computer(capabilities,click,drag,get-app-state,hotkey,list-apps,list-windows,paste-text,permissions,press-key,scroll,set-value,type-text), agent-hooks(status/on/off), diagnostics(memory), emulator(attach,ax,button,devices,exec,gesture,install,kill,launch,list,logcat,permissions,rotate,shutdown,tap,type), environment(add/list/rm/show), linear(issue,create,search,list,comment add,attach,assignee set/clear,due-date set/clear,estimate set/clear,label add/remove/set,status set,priority set/clear,project list,team list/members/states/labels), vm(recipe doctor), orchestration(send,check,reply,ask,inbox,run,run-stop,reset,task-create/task-list/task-update,dispatch/dispatch-show,gate-create/gate-list/gate-resolve). Flags globais: --json etc. --agent <id> em worktree create lança o agente no primeiro terminal.','src/cli/specs/index.ts','f8fb162c20cf8cdd92cdfa3003dfe2bcebfddd083515db2a51fe5a67b6c2ee24','orca,cli,command-surface,worktrees,agents,automations,browser,computer-use,emulator,linear,orchestration',2.4);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:orca:worktree-model-v1','project_doc','seed://orca/worktree-model','Orca worktree id model & selectors','Orca worktree id é um endereço de duas partes: `<repoId>::<worktreePath>` (ex: `repo-123::/Users/me/orca/fix-login`). SEMPRE copiar o id completo de `orca worktree create --json` / `orca worktree list --json`; um repo id sozinho NÃO endereça o worktree. Selectors: `id:<repoId>::<path>`, `name:<displayName>`, `path:<absPath>`, `branch:<branch>`, `issue:<n>`, `active`/`current` (worktree do cwd). Lineage: `--parent-worktree active|folder:<id>|worktree:<id>` para stacked work; `--no-parent` para trabalho top-level independente (só controla lineage Orca, NÃO a git base — para base independente omitir `--base-branch`, que usa o default do repo). `worktree create --agent <id> --prompt <text>` é o caminho agent-first (sem fallback shell). `terminal wait --for tui-idle --timeout-ms <n>` ANTES de dispatch; agentes CLI demoram 15-60min.','skills/orca-cli/SKILL.md','8892b52fc9e75d8505aadaa55f7d2416752320e3c09f02f43acb2222f543b62d','orca,worktree,selectors,lineage,git,orchestration',2.3);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:orca:orchestration-layer-v1','project_doc','seed://orca/orchestration','Orca orchestration — coordinated multi-agent layer','Orca orchestration (skills/orchestration/SKILL.md) é a camada estruturada de coordenação: mensagens threaded entre agent terminals, task DAGs com dependências, dispatch de tarefas a workers, decision gates, e coordinator loops. Comandos: `orca orchestration send/check/reply/ask/inbox`, `task-create/task-list/task-update`, `dispatch/dispatch-show`, `gate-create/gate-list/gate-resolve`, `run/run-stop`. Task statuses: pending/ready/dispatched/completed/failed/blocked. `worker_done` (com taskId+dispatchId) é autoridade de completude para UM dispatch; enviar de terminal próprio. Diferença CRÍTICA: orchestration = coordenação supervisionada (cria runtime state, lifecycle, provenance); full handoff = transferência de ownership (usar `orca worktree create --no-parent --agent <id> --prompt` + parar de monitorar). NUNCA usar task-create/dispatch --inject/check --wait para full handoff. Group addresses: @all,@idle,@claude,@codex,@opencode,@gemini,@droid,@grok,@worktree:<id>. Precisa feature flag Settings>Experimental.','skills/orchestration/SKILL.md','bb70f3e1b8952fd5cda239291b23b60645d2ab2cb6616af6808ee51daab20314','orca,orchestration,multi-agent,dispatch,gates,handoff,coordination',2.3);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:orca:integration-points-v1','project_doc','seed://orca/integration','Orca x Simplicio — pontos de integração e gaps','Orca e Simplicio são ambos orquestradores de agentes CLI, mas em layers diferentes: Orca = desktop GUI + worktree/terminal/browser management + mobile; Simplicio = control-plane determinístico (edit/validate/evidence/gate) + local fan-out 64→600 + neural memory. Pontos de sinergia: (1) Simplicio como UM dos agents suportados pelo Orca (já listado em README como ''Hermes Agent''); (2) `orca worktree create --agent <id>` poderia spawnar o Simplicio Runtime local como worker; (3) Simplicio memory/evidence poderia alimentar o ''annotate AI diffs'' do Orca. GAP conhecido do Simplicio Runtime descoberto nesta absorção: `simplicio runtime map --repo <dir>` IGNORA o --repo para repos não-Simplicio e emite o map do próprio runtime (drift). Reportar como issue no simplicio-runtime. GAP do ingest: `simplicio memory ingest` falha com ''ingest orchestrator not found'' quando rodado de cwd que não o simplicio-runtime (espera scripts/ingest_project.py relativo).','README.md','6eec4e2d3c6d8f5a2b4a639e4ef8eb729ca81e37947b042eeabea793eafaf8c2','orca,simplicio,integration,gaps,runtime-map-drift,ingest-cwd',2.1);
INSERT OR IGNORE INTO schema_migrations(id) VALUES ('0006_orca_absorption');
COMMIT;
